-- Application Tables for Bank Statement and Academic Transcript
CREATE TABLE IF NOT EXISTS applicationacademictranscript (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(255), national_id VARCHAR(20), school_name VARCHAR(255), grad_year INT, document_path VARCHAR(512), service_name VARCHAR(255), status ENUM('Pending', 'Approved', 'Rejected') DEFAULT 'Pending', ai_forgery_score FLOAT, ai_verdict VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
